1	type Cell = [number, number]; // [x, y]
2	
3	function cellEquals([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function contains(cells: Cell[], cell: Cell): boolean {
8	  return cells.some((other) => cellEquals(cell, other));
9	}
10	
11	function neighborsOf([x, y]: Cell): Cell[] {
12	  const neighbors: Cell[] = [];
13	  for (let dx = -1; dx <= 1; dx++) {
14	    for (let dy = -1; dy <= 1; dy++) {
15	      if (dx !== 0 || dy !== 0) {
16	        neighbors.push([x + dx, y + dy]);
17	      }
18	    }
19	  }
20	  return neighbors;
21	}
22	
23	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
24	  return neighborsOf(cell).filter((neighbor) => contains(liveCells, neighbor))
25	    .length;
26	}
27	
28	function survives(cell: Cell, liveCells: Cell[]): boolean {
29	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
30	  return liveNeighbors === 2 || liveNeighbors === 3;
31	}
32	
33	function uniqueCells(cells: Cell[]): Cell[] {
34	  return cells.filter(
35	    (cell, index) => cells.findIndex((other) => cellEquals(cell, other)) === index
36	  );
37	}
38	
39	function deadNeighborsOfLiveCells(liveCells: Cell[]): Cell[] {
40	  const allNeighbors = liveCells.flatMap(neighborsOf);
41	  const deadNeighbors = allNeighbors.filter((cell) => !contains(liveCells, cell));
42	  return uniqueCells(deadNeighbors);
43	}
44	
45	export function nextGeneration(liveCells: Cell[]): Cell[] {
46	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
47	  const born = deadNeighborsOfLiveCells(liveCells).filter(
48	    (cell) => countLiveNeighbors(cell, liveCells) === 3
49	  );
50	  return [...survivors, ...born];
51	}
52

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  // Simplest case: empty grid
6	  it("returns an empty array for an empty grid", () => {
7	    expect(nextGeneration([])).toEqual([]);
8	  });
9	
10	  // Single cell dies (pattern example)
11	  it("a single live cell dies from underpopulation — [(0,0)] → []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	
15	  // Rule 1 - Underpopulation
16	  it("two adjacent live cells both die (each has 1 neighbor) — [(0,1),(1,1)] → []", () => {
17	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
18	  });
19	
20	  // Rule 2 - Survival
21	  it("center cell with 3 neighbors survives — center (1,1) lives on", () => {
22	    // (1,1) is alive and has 3 live neighbors: (0,2),(1,2),(2,2)
23	    const next = nextGeneration([[0, 2], [1, 2], [2, 2], [1, 1]]);
24	    expect(next).toContainEqual([1, 1]);
25	  });
26	
27	  // Rule 3 - Overpopulation
28	  it("center cell with 4 neighbors dies — center (1,1) dies", () => {
29	    // (1,1) is alive with 4 live neighbors: the four corners
30	    const next = nextGeneration([[0, 0], [2, 0], [0, 2], [2, 2], [1, 1]]);
31	    expect(next).not.toContainEqual([1, 1]);
32	  });
33	
34	  // Rule 4 - Reproduction
35	  it("dead cell with exactly 3 neighbors becomes alive — (1,1) born", () => {
36	    // dead cell (1,1) has 3 live neighbors: (0,2),(1,2),(0,1)
37	    const next = nextGeneration([[0, 2], [1, 2], [0, 1]]);
38	    expect(next).toContainEqual([1, 1]);
39	  });
40	
41	  // Pattern: Block (still life)
42	  it("block still life is unchanged — [(0,0),(1,0),(0,1),(1,1)] stays the same", () => {
43	    const block: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
44	    const next = nextGeneration(block);
45	    expect(next).toHaveLength(4);
46	    expect(next).toEqual(expect.arrayContaining(block));
47	  });
48	
49	  // Pattern: Blinker (oscillator)
50	  it("blinker rotates — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
51	    const next = nextGeneration([[0, 0], [0, 1], [0, 2]]);
52	    expect(next).toHaveLength(3);
53	    expect(next).toEqual(
54	      expect.arrayContaining([[-1, 1], [0, 1], [1, 1]])
55	    );
56	  });
57	
58	  // Negative coordinates
59	  it("handles negative coordinates correctly", () => {
60	    // vertical blinker in negative space rotates to horizontal
61	    const next = nextGeneration([[-5, -5], [-5, -4], [-5, -3]]);
62	    expect(next).toHaveLength(3);
63	    expect(next).toEqual(
64	      expect.arrayContaining([[-6, -4], [-5, -4], [-4, -4]])
65	    );
66	  });
67	});
